L={
"95A3AC6488":(2,"Nêu tác dụng điều hòa cảm giác của nước và các rủi ro cảm giác/áo phao khi học bơi.","This sensory input can have a regulating effect on their child.","high"),
"EEEEDBD3BF":(2,"Nêu lưu ý an toàn: trẻ không nhận ra mệt nên có thể cạn sức khi bơi, cần giám sát; cũng nhắc nước là nơi bình ổn.","he can swim for a long time and at some point he…will continue and he will not [realize that he doesn’t] have enough energy anymore to stay afloat","high"),
"CB88D1720C":(1,"Nói về rủi ro đuối nước và khó tiếp cận thông tin/lớp bơi, chỉ gián tiếp về lợi ích và lưu ý an toàn.","Despite the increased risk of drowning among autistic children and water safety risks","medium"),
"6C31FF6BB5":(3,"Nêu trực tiếp lợi ích: nước điều hòa kích thích, cải thiện chú ý, điều hòa ở nhà, tăng tương tác xã hội.","the sensory qualities of the water helped to regulate their level of arousal, sometimes resulting in reports of better attention in the classroom or better regulation at home after lessons","high"),
"8D15555B4F":(2,"Kết luận nhấn mạnh nguy cơ đuối nước cao, cần giám sát, rào chắn và lớp bơi thích ứng cho trẻ tự kỷ.","the importance of supervision and utilizing barriers to water access","high"),
"C3EF7F0ED0":(2,"Tóm tắt nêu đuối nước là nguyên nhân tử vong hàng đầu và các yếu tố nguy cơ (lang thang, giác quan, bốc đồng).","Among children with autism, drowning is the leading cause of death through 14 years old.","high"),
"C85A48A7D3":(1,"Bảng trích dẫn về nhu cầu lớp bơi (môi trường riêng, giáo viên hiểu tự kỷ), liên quan một phần đến lưu ý khi học bơi.","It is important that there are instructors who know how to work with autistic kids","medium"),
"C740C8D96E":(1,"Chủ yếu bàn rào cản tài chính và tập huấn giáo viên; chỉ nhắc ngắn việc giảm lo âu của trẻ.","could help with logistics, increase the water competence of parents, and reduce the autistic child’s anxiety around lessons","medium"),
"9B9E816929":(3,"Nêu cả lý do an toàn (kỹ năng sinh tồn, trẻ không hiểu nguy hiểm) và lợi ích (vận động, tư thế, chú ý, điều hòa).","swimming has provided their children with exercise that, in some cases, has improved their posture and participation at school","high"),
"5E22DEB71C":(1,"Thảo luận chung về rào cản, thông tin phòng đuối nước và đào tạo giáo viên; gián tiếp với câu hỏi.","information on drowning risk and prevention should be proactively provided in settings where families frequent","medium"),
"836B3526C3":(2,"Nêu trẻ tự kỷ có nguy cơ đuối nước cao hơn, bơi là kỹ năng sinh tồn và mang lại ý nghĩa/kết nối cho gia đình.","Parent participants’ initial concern regarding their children being at a higher risk of drowning than typically developing children is well supported by literature","high"),
"B178733949":(1,"Về trải nghiệm và nhu cầu đào tạo của giáo viên dạy bơi, chỉ gián tiếp với câu hỏi.","Teacher participants’ expressed desire for more support and training","medium"),
"E8477D1AC2":(3,"Nêu lợi ích của bơi/liệu pháp thủy sinh: kỹ năng vận động, sức mạnh, lòng tự trọng, tự điều hòa, hành vi lặp lại.","benefits for motor skill development, muscle strength and endurance, self-esteem, self-regulation, and repetitive behaviors","high"),
"B23E19041A":(1,"Bảng chỉ liệt kê tiêu đề chủ đề (bị thu hút bởi nước, kém nhận thức nguy hiểm, lang thang), không giải thích.","Poor sense of danger","medium"),
"4B8A286EE1":(1,"Các trích dẫn rời rạc về cảm giác nước và nhu cầu lớp bơi, chỉ một phần liên quan.","The [bath] water relaxes her.","low"),
"7643B61F65":(3,"Nêu nguy cơ đuối nước cao ở trẻ tự kỷ, khuyến cáo WHO dạy kỹ năng bơi, và trẻ có thể học bơi cơ bản nếu giáo viên có kỹ năng.","children with autism are capable of learning basic swim skills","high"),
"023E7F1420":(1,"Bàn nhu cầu thiết kế lớp bơi (nhóm nhỏ, mức phát triển, phụ huynh tham gia), không nêu trực tiếp lợi ích hay an toàn.","Many parents indicated that their child with autism benefited from small group or individual lessons.","medium"),
"E0AA5E701C":(1,"Trải nghiệm giáo viên; chỉ nhắc ngắn trẻ thích bơi, không chỉ vì an toàn.","It is not just for safety anymore.","low"),
"6A3CA100C2":(2,"Bảng chủ đề có nêu bơi để điều hòa cảm giác, cải thiện các hoạt động khác và đặt mục tiêu/an toàn.","Swimming for sensory regulation—inherently therapeutic","medium"),
}
